using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;
using Xunit;

namespace MyApp.Evaluation;

public class EvaluationTests : IAsyncLifetime
{
    private DistributedApplicationTestingBuilder _builder = null!;
    private DistributedApplication _app = null!;
    private IChatClient _chatClient = null!;
    private IChatClient _evaluatorClient = null!;

    public async ValueTask InitializeAsync()
    {
        _builder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _builder.BuildAsync();
        await _app.StartAsync();

        _chatClient = _app.Services.GetRequiredService<IChatClient>();
        _evaluatorClient = _app.Services.GetRequiredService<IChatClient>();
    }

    public async ValueTask DisposeAsync()
    {
        await _app.DisposeAsync();
        await _builder.DisposeAsync();
    }

    private ReportingConfiguration CreateReportingConfiguration()
    {
        return new ReportingConfiguration(
            storageRootPath: Path.Combine(Directory.GetCurrentDirectory(), "eval-results"),
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            ],
            chatConfiguration: new ChatConfiguration(_evaluatorClient));
    }

    [Fact]
    public async Task Evaluate_SimpleQuery_MeetsQualityThresholds()
    {
        var reportingConfig = CreateReportingConfiguration();

        await using var scenario = await reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Evaluate_SimpleQuery_MeetsQualityThresholds));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await scenario.EvaluateAsync(messages);

        foreach (var metric in scenario.GetAllMetrics())
        {
            if (metric is NumericMetric numericMetric)
            {
                Assert.True(
                    numericMetric.Value >= 3,
                    $"Metric '{metric.Name}' scored {numericMetric.Value}, expected >= 3");
            }
        }
    }

    [Fact]
    public async Task Evaluate_FollowUpQuery_MaintainsContext()
    {
        var reportingConfig = CreateReportingConfiguration();

        await using var scenario = await reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Evaluate_FollowUpQuery_MaintainsContext));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "My name is Alice."),
        };

        var response1 = await _chatClient.GetResponseAsync(messages);
        messages.AddRange(response1.Messages);

        messages.Add(new ChatMessage(ChatRole.User, "What is my name?"));
        var response2 = await _chatClient.GetResponseAsync(messages);
        messages.AddRange(response2.Messages);

        await scenario.EvaluateAsync(messages);

        var lastResponse = messages.Last(m => m.Role == ChatRole.Assistant);
        Assert.Contains("Alice", lastResponse.Text, StringComparison.OrdinalIgnoreCase);
    }
}

